package org.mockito.internal.creation;

import java.io.*;
import java.lang.reflect.Method;
import java.lang.reflect.Modifier;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import org.mockito.internal.invocation.MockitoMethod;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class DelegatingMethod_equals_TriageGen0Test {

    @Test
    public void testEquals_SameObject() throws NoSuchMethodException {
        Method method = String.class.getMethod("length");
        DelegatingMethod delegatingMethod = new DelegatingMethod(method);

        // Since the implementation is method.equals(o), 
        // and 'o' is passed to the internal method object's equals.
        // We test if delegatingMethod.equals(delegatingMethod) works.
        // Note: The provided code snippet 'return method.equals(o)' implies 
        // it delegates equality to the underlying Method object.

        assertTrue(delegatingMethod.equals(delegatingMethod));
    }






}

package org.mockito.internal.creation;

import java.io.*;
import java.lang.reflect.Method;
import java.lang.reflect.Modifier;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import org.mockito.internal.invocation.MockitoMethod;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class DelegatingMethod_equals_TriageGen0Test {



    @Test
    public void testEquals_DifferentObject() throws NoSuchMethodException {
        Method method1 = String.class.getMethod("length");
        Method method2 = String.class.getMethod("isEmpty");

        DelegatingMethod delegatingMethod1 = new DelegatingMethod(method1);
        DelegatingMethod delegatingMethod2 = new DelegatingMethod(method2);

        assertFalse(delegatingMethod1.equals(delegatingMethod2));
    }




}

